    #[test]
    fn concurrent_writes_do_not_corrupt_content() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));
        store.ensure_dir().unwrap();

        let mut handles = vec![];

        // Spawn multiple threads writing to the same cache entry
        for i in 0..10 {
            let store = Arc::clone(&store);
            handles.push(thread::spawn(move || {
                let content = format!("content-from-thread-{}", i);
                store
                    .store("http:test", "shared-template", &content, 3600)
                    .unwrap();
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // The entry must be readable and valid (one of the writers wins)
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert!(content.starts_with("content-from-thread-"));

        // Metadata must be valid JSON (not corrupted)
        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "shared-template");
    }

    #[test]
    fn concurrent_writes_to_different_entries() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));
        store.ensure_dir().unwrap();

        let mut handles = vec![];

        // Spawn threads each writing to their own entry
        for i in 0..10 {
            let store = Arc::clone(&store);
            handles.push(thread::spawn(move || {
                let name = format!("template-{}", i);
                let content = format!("content-{}", i);
                store.store("http:test", &name, &content, 3600).unwrap();
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        // Each entry should have correct content
        for i in 0..10 {
            let name = format!("template-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, format!("content-{}", i));
        }
    }

    #[test]
    fn concurrent_reads_during_write() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        // Seed an initial entry
        store
            .store("http:test", "template", "initial-content", 3600)
            .unwrap();

        let barrier = Arc::new(Barrier::new(6));
        let mut handles = vec![];

        // 3 writers
        for i in 0..3 {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                barrier.wait();
                let content = format!("updated-by-{}", i);
                store
                    .store("http:test", "template", &content, 3600)
                    .unwrap();
            }));
        }

        // 3 readers
        for _ in 0..3 {
            let store = Arc::clone(&store);
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                barrier.wait();
                // Readers should never see partial/corrupt data
                if let Ok(Some(entry)) = store.load("http:test", "template") {
                    let content = store.read_content(&entry).unwrap();
                    // Content must be one of the valid values, never partial
                    assert!(
                        content.starts_with("initial-content")
                            || content.starts_with("updated-by-"),
                        "Got corrupted content: {}",
                        content
                    );
                }
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }
    }
