/// Write a file atomically using write-to-temp-then-rename.
///
/// This prevents readers from seeing partially-written files when
/// multiple processes write to the same cache entry concurrently.
fn atomic_write(&self, target: &Path, content: &[u8]) -> Result<()> {
    let mut tmp = NamedTempFile::new_in(&self.root)
        .with_context(|| format!("Failed to create temp file in {:?}", self.root))?;
